string output=Path.GetFullPath(args[0]);Directory.CreateDirectory(output);
if(File.Exists(Path.Combine(output,"summary.json")))throw new Exception("Conclusive HDR UI receipt already exists.");
string data=Path.Combine(output,"fixture"),inf=Path.Combine(data,"inference");foreach(var dir in new[]{data,inf,Path.Combine(data,"onnx"),Path.Combine(data,"rife")})Directory.CreateDirectory(dir);
