foreach(var name in new[]{"libnvinfer.so.11","aji_pipeline.fatbin","libaji_trt.so"})File.WriteAllText(Path.Combine(inf,name),"UI fixture only");File.Copy(Path.GetFullPath(args[1]),Path.Combine(inf,"libaji_pipeline.so"),true);
