File.WriteAllText(Path.Combine(data,"animejanai.conf"),"# legacy profile retained\n[global]\nconfig_version=3\nbackend=TensorRT\nrife_engine=quality\ndefault_slot=1\n[slot_1]\nprofile_name=Legacy\nchain_1_rife=yes\nchain_1_rife_model=426\nchain_1_rife_factor_numerator=2\nchain_1_rife_factor_denominator=1\n");
AppBuilder.Configure<AnimeJaNaiConfEditor.App>().UseSkia().UseHeadless(new AvaloniaHeadlessPlatformOptions{UseHeadlessDrawing=false}).WithInterFont().UseReactiveUI(_=>{}).SetupWithoutStarting();
var checks=new List<string>();void Check(string name,bool ok){if(!ok)throw new Exception(name);checks.Add(name);Console.WriteLine("PASS "+name);}
var vm=new MainWindowViewModel();vm.HandleShowCustomProfile("1");vm.AnimeJaNaiConf.SetTensorRtSelected();var chain=vm.CurrentSlot.Chains[0];chain.EnableOrderedPipeline();
var view=new InterpolationStages{DataContext=chain};var window=new Window{Content=new ScrollViewer{Content=view},Width=1100,Height=1250};window.Show();Dispatcher.UIThread.RunJobs();
Check("imported profile keeps legacy HDR behavior before explicit adoption",vm.LegacyHdrConversionVisible&&!vm.CurrentSlot.HdrStageControlled);
var add=view.GetVisualDescendants().OfType<Button>().Single(b=>Equals(b.Content,"Add HDR"));Check("installed SDK and new native capability enable Add HDR",add.IsEnabled&&vm.OptionalSdks.TrueHdrReady);add.Command!.Execute(null);Dispatcher.UIThread.RunJobs();var hdr=chain.Stages.Last();string id=hdr.Id;
Check("add creates a fixed inactive HDR category with one technology",hdr.IsHdr&&!hdr.Enabled&&hdr.Category=="HDR"&&hdr.MethodChoices.SequenceEqual(new[]{"NVIDIA TrueHDR"})&&!hdr.HasModel&&!hdr.IsRife);
Check("adoption reserves one HDR for the profile and hides legacy conversion controls",!add.IsEnabled&&!vm.LegacyHdrConversionVisible&&vm.CurrentSlot.HdrStageControlled&&chain.ProfileHdrCount==1);
chain.AddHdrStage();Check("repeated command cannot add a second HDR",chain.Stages.Count(s=>s.IsHdr)==1);
hdr.Enabled=true;Dispatcher.UIThread.RunJobs();Check("HDR activation keeps RIFE quality and cadence unchanged",hdr.CanEnable&&chain.Stages[0].Policy=="quality"&&chain.PipelineCadence.StartsWith("24 → 48")&&chain.PipelineOrder.EndsWith("NVIDIA TrueHDR → HDR10 → Display"));
var peak=view.GetVisualDescendants().OfType<TextBox>().Single(b=>b.Name=="HdrPeak"&&ReferenceEquals(b.DataContext,hdr));var contrast=vm.HdrSettings.RtxContrast;peak.Text="1500";hdr.HdrContrast="75";Dispatcher.UIThread.RunJobs();Check("stage HDR parameters do not modify legacy global settings",hdr.HdrPeak=="1500"&&hdr.HdrContrast=="75"&&vm.HdrSettings.RtxContrast==contrast);
string saved=Path.Combine(output,"saved.conf");vm.WriteAnimeJaNaiConf(saved);var reloaded=vm.ReadAnimeJaNaiConf(saved);var loaded=reloaded.UpscaleSlots[0].Chains[0].Stages.Last();Check("save reload preserves HDR ownership identity SDK root and tunables",reloaded.UpscaleSlots[0].HdrStageControlled&&loaded.Id==id&&loaded.HdrPeak=="1500"&&loaded.HdrContrast=="75"&&loaded.HdrSdkRoot==hdr.HdrSdkRoot);
string source=Path.Combine(data,"animejanai.conf"),before=File.ReadAllText(source);hdr.MoveUp();Check("unsupported HDR before RIFE order cannot overwrite valid configuration",File.ReadAllText(source)==before&&chain.PipelineNotice.Contains("last active"));hdr.MoveDown();
before=File.ReadAllText(source);hdr.HdrPeak="300";Check("invalid HDR peak is refused with last valid file intact",File.ReadAllText(source)==before&&vm.BackendNotice.Contains("400 to 2000"));hdr.HdrPeak="1000";
chain.AddUpscaleStage();Check("new SDR processor is inserted before the HDR tail without moving existing stages",chain.Stages.Last()==hdr&&chain.Stages[^2].IsUpscale&&chain.Stages[0].IsRife);chain.Stages[^2].Remove();
Check("profile export carries explicit HDR ownership",vm.ParsedAnimeJaNaiProfileConf(vm.CurrentSlot).GetValue("slot","hdr_stage_controlled")=="yes");
using(var frame=window.CaptureRenderedFrame()){if(frame==null)throw new Exception("No frame");frame.Save(Path.Combine(output,"hdr-stage.png"));}
hdr.Remove();vm.WriteAnimeJaNaiConf(saved);reloaded=vm.ReadAnimeJaNaiConf(saved);Check("removing HDR keeps conversion off after reload instead of reviving legacy conversion",vm.CurrentSlot.HdrStageControlled&&!vm.LegacyHdrConversionVisible&&reloaded.UpscaleSlots[0].HdrStageControlled&&!reloaded.UpscaleSlots[0].Chains[0].Stages.Any(s=>s.IsHdr));
string? oldRoot=Environment.GetEnvironmentVariable("ANIMEJANAI_VFX_SDK");Environment.SetEnvironmentVariable("ANIMEJANAI_VFX_SDK",Path.Combine(output,"missing-sdk"));vm.OptionalSdks.Refresh();Dispatcher.UIThread.RunJobs();Check("missing SDK disables HDR without manual path fields",!add.IsEnabled&&!vm.OptionalSdks.TrueHdrReady);Environment.SetEnvironmentVariable("ANIMEJANAI_VFX_SDK",oldRoot);vm.OptionalSdks.Refresh();window.Close();
File.WriteAllText(Path.Combine(output,"summary.json"),JsonSerializer.Serialize(new{passed=true,checks,scope="New HDR UI migration/settings/capability guards only. Native SDK pixels and actual player tested separately."},new JsonSerializerOptions{WriteIndented=true}));
